        <img src="/projects/re-diseno-la-cometa/assets/img/artista-daniel-nystrom.webp" alt="Retrato de Daniel Nyström" loading="lazy" decoding="async">
      </figure>
    </div>
  </section>

  <!-- Navegación contextual: la ficha completa sin volver al menú (ref. Pace Gallery) -->
